def transform_rule(grid):
    """Fill gaps between foreground cells in diagonal pattern."""
    from collections import Counter
    cells = sum(grid, [])
    if not cells:
        return grid
    bg = Counter(cells).most_common(1)[0][0]

    result = [row[:] for row in grid]

    for iy in range(len(result)):
        # Find foreground positions
        fg_positions = [ix for ix in range(len(result[0])) if result[iy][ix] != bg]

        if len(fg_positions) < 2:
            continue

        # Fill gaps between consecutive fg positions
        for i in range(len(fg_positions) - 1):
            left = fg_positions[i]
            right = fg_positions[i+1]

            # Determine target parity: opposite of row
            target_parity = 1 - (iy % 2)  # If row is even (0), target odd (1); if row is odd (1), target even (0)

            # Fill positions between them with the target parity
            for ix in range(left + 1, right):
                pos_sum = iy + ix
                if pos_sum % 2 == target_parity:
                    result[iy][ix] = 2  # Fill with 2

    return result

